// Contract (input): { payload: object, required: string[], maxLen?: number }
// Fails fast with a clear error, otherwise passes { valid:true, payload } through.
const i = $json || {};
const payload = i.payload || {};
const required = i.required || [];
const maxLen = i.maxLen || 8000;
const missing = required.filter(k => payload[k] === undefined || payload[k] === null || payload[k] === '');
if (missing.length) {
  throw new Error('validate-input: missing required fields: ' + missing.join(', '));
}
for (const [k, v] of Object.entries(payload)) {
  if (typeof v === 'string' && v.length > maxLen) {
    throw new Error(`validate-input: field '${k}' exceeds maxLen ${maxLen}`);
  }
}
return [{ json: { valid: true, payload } }];
